#[derive(Debug, Clone, Default, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ModelCost {
    pub source: String,
    pub model: String,
    pub has_price: bool,
    pub priced_requests: u64,
    pub unpriced_requests: u64,
    pub cost: f64,
